mapper.update:
update user_presence_visits
set offline_at = timestampadd(second, #{timeout}, last_seen_at), end_reason = 'TIMEOUT'
where user_id = #{userId} and active_client = #{clientId} and last_seen_at <= #{cutoff}

mapper.select:
select user_id, client_id from user_presence_visits
where offline_at is null and last_seen_at <= #{cutoff}
order by last_seen_at, id limit #{limit}

select id, online_at,
       coalesce(offline_at, if(last_seen_at <= #{cutoff}, timestampadd(second, #{timeout}, last_seen_at), null)) offline_at,
       coalesce(end_reason, if(last_seen_at <= #{cutoff}, 'TIMEOUT', null)) end_reason
from user_presence_visits where user_id = #{userId}
order by online_at desc, id desc limit #{limit} offset #{offset}
